//Es hija de Dispositivo, implementa las interfaces Controlable y regulable
public class Luminaria extends Dispositivo implements Controlable, Regulable {
	//Nivel de intensidad entre 10 y 100
    private int nivel;


    // Constructor default, con super para los datos que ya teniamos
    public Luminaria() {
        super();
		//El nivel comienza en 100 (el valor que se había dicho)
        nivel = 100;
    }


    // Constructor con atributos ya
    public Luminaria(String codigo, Oficina oficina, double potenciaNominal) {
        super(codigo, oficina, potenciaNominal);
        nivel = 100;
    }


    // Getter del Nivel
    public int getNivel() {
        return nivel;
    }


    // usa el metodo encender de Controlable
    @Override
    public boolean encender() {
        if (encendido) {
            return false;
        }

        encendido = true;
        return true;
    }


    // usa el método apagar de Controlable
    @Override
    public boolean apagar() {
        if (!encendido) {
            return false;
        }
        encendido = false;
        return true;
    }


    // Permitir ajustar nivel con un número ingresado (solo números válidos)
    @Override
    public boolean ajustarNivel(int nivel) {

        if (!encendido) {
            return false;
        }

        if (nivel < 10 || nivel > 100) {
            return false;
        }

        this.nivel = nivel;
        return true;
    }


    // Calcular consumo por hora
    // Sobrescribe el metodo abstracto de Dispositivo
    // Si esta apagada, no consume electricidad
    // Si esta encendida, utiliza su potencia y nivel
    // Divide entre 1000 para convertir watts a kWh

    @Override
    public double calcularConsumoHora() {
		//Si está apagado, consume 0 en esta hora.
        if (!encendido) {
            return 0;
        }
		//Si está encendido, haga la siguiente formula:
        return (potenciaNominal * nivel / 100.0) / 1000.0;
		//el último /1000 es para que sea expresado en kW.
    }


    // toString
    // Agrega el nivel de intensidad de la luminaria a lo que ya teníamos antes

    @Override
    public String toString() {
        return super.toString() + "\nNivel de intensidad: " + nivel + "%";
    }
}
